<script lang="ts">
	import { invalidateAll } from '$app/navigation'; import { api } from '$lib/api';
	let {data}=$props(); let search=$state('');let creating=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');
	const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const doctors=$derived(data.user.role==='DOKTER');
	const filtered=$derived(data.records.filter((r:any)=>!search||`${r.patientName} ${r.medicalRecordNo} ${r.diagnosis}`.toLowerCase().includes(search.toLowerCase())));
	async function create(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);busy=true;error='';try{const row=await api<any>('/medical-records',{method:'POST',body:JSON.stringify({patientId:f.get('patientId'),complaint:f.get('complaint'),diagnosis:f.get('diagnosis'),treatment:f.get('treatment'),notes:f.get('notes'),recordDate:f.get('recordDate')})});await invalidateAll();creating=false;notice='Rekam medis tersimpan.';location.href=`/medical-records/${row.id}`;}catch(e){error=e instanceof Error?e.message:'Rekam medis gagal disimpan.';}finally{busy=false;}}
</script>

<svelte:head><title>Rekam Medis | InpaCare</title></svelte:head>
<section class="page-heading"><div><h1 class="page-title">Daftar Rekam Medis</h1><p class="page-subtitle">Catatan dokter dan observasi keperawatan pasien rawat inap.</p></div>{#if doctors}<button class="button primary" onclick={()=>{creating=!creating;error='';}}>＋ Tambah rekam medis</button>{/if}</section>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="success" role="status">{notice}</p>{/if}
<section class="stats"><div class="stat"><strong>{data.records.length}</strong><span>Catatan dalam cakupan Anda</span></div><div class="stat"><strong>{data.records.filter((r:any)=>r.recordDate===today).length}</strong><span>Rekam medis hari ini</span></div><div class="stat"><strong>{data.records.reduce((n:number,r:any)=>n+Number(r.observationCount),0)}</strong><span>Observasi tersimpan</span></div></section>
{#if creating&&doctors}<section class="panel form-panel"><h2>Tambah rekam medis</h2><form class="form-grid" onsubmit={create}><label class="field">Pasien<select name="patientId" required><option value="">Pilih pasien yang ditangani</option>{#each data.reference.patients as patient}<option value={patient.id}>{patient.name} · {patient.medicalRecordNo}</option>{/each}</select></label><label class="field">Tanggal rekam medis<input type="date" name="recordDate" value={today} required /></label><label class="field">Keluhan<textarea name="complaint" rows="2" required maxlength="5000"></textarea></label><label class="field">Diagnosis<textarea name="diagnosis" rows="2" required maxlength="5000"></textarea></label><label class="field">Tindakan<textarea name="treatment" rows="2" required maxlength="5000"></textarea></label><label class="field">Catatan medis<textarea name="notes" rows="2" maxlength="5000"></textarea></label><div class="form-actions"><button class="button primary" disabled={busy}>Simpan rekam medis</button><button class="button secondary" type="button" onclick={()=>creating=false}>Batal</button></div></form></section>{/if}
<section class="panel"><div class="filters"><label class="field search-field">Cari pasien atau rekam medis<input bind:value={search} placeholder="Nama pasien, nomor RM, diagnosis" /></label><span class="muted">Menampilkan {filtered.length} dari {data.records.length}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>No. RM / pasien</th><th>Diagnosis</th><th>Tanggal</th><th>Dokter</th><th>Observasi</th><th>Aksi</th></tr></thead><tbody>{#each filtered as record (record.id)}<tr><td><strong>{record.patientName}</strong><span class="cell-meta">{record.medicalRecordNo}</span></td><td>{record.diagnosis}</td><td>{new Date(record.recordDate+'T12:00:00').toLocaleDateString('id-ID')}</td><td>{record.doctorName}</td><td>{record.observationCount}</td><td><a class="text-link" href={'/medical-records/'+record.id}>Lihat detail →</a></td></tr>{:else}<tr><td colspan="6" class="empty">Tidak ada rekam medis dalam cakupan Anda.</td></tr>{/each}</tbody></table></div></section>
